using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public static class ProbeScanningTests
{
 static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception("PROBE FAIL: "+label);checks++;Console.WriteLine("PROBE PASS: "+label);}
 static DemoWorld World(int count=8,bool combat=false){var w=new DemoWorld();w.NewGame(0);w.Screen=ViewMode.Space;w.Grid="utility_range";w.SolarCelestial="";w.SolarOrigin=default;w.SolarGrids.Clear();w.Targets.Clear();w.Player.Position=Vector3.Zero;w.ProbeCenter=new(.05f,.02f,.03f);w.ProbeRange=.25f;w.UtilitySites=[new(){Id="scan-unit",System=w.SystemId,Kind="Data",Name="Test Archive",X=.05f,Y=.02f,Z=.03f,Difficulty=1}];for(int i=0;i<count;i++)w.ScanProbes.Add(new(){System=w.SystemId,Payload=combat?"ut_probe_combat":"ut_probe_core"});return w;}
 static UtilitySite Site(DemoWorld w)=>w.UtilitySites.First(s=>s.Id=="scan-unit");
 static void Scan(DemoWorld w){Check(w.AnalyzeUtilityProbes(),"Analyze starts with active probes");w.UpdateUtility(w.ProbeScanLeft+.01f);Check(w.ProbeScanLeft==0,"Analysis finishes after actual duration");}
 public static void Run(){checks=0;
 var empty=World(0);empty.RefreshProbeResults();Check(!empty.AnalyzeUtilityProbes(),"No imaginary scan without deployed probes");Check(empty.UtilitySites.Any(s=>s.Anomaly&&s.Signal==100),"Anomalies appear resolved without probe equipment");Check(empty.UtilitySites.Where(s=>s.TargetId.Length==0&&!s.Anomaly).All(s=>s.Signal==0),"Signatures remain unresolved without probes");
 for(int n=1;n<=8;n++){var w=World(n);Scan(w);var s=Site(w);Check(s.HitCount==n,"Individual coverage count "+n);Check(s.ResultShape==(n==1?"Sphere":n==2?"Circle":n==3?"Two points":"Point"),"Geometric result shape "+n);Check(n>=4?s.Signal==100:s.Signal<100,"Four non-coplanar probes required for resolution "+n);}
 var geometry=World();geometry.ProbeLayoutCustomized=true;foreach(var p in geometry.ScanProbes)geometry.PlanProbe(p,geometry.ProbeCenter,.25f);Scan(geometry);Check(Site(geometry).Signal<100,"Coincident probes cannot triangulate a full result");foreach(var p in geometry.ScanProbes)geometry.PlanProbe(p,geometry.ProbeCenter+Vector3.UnitY*100,.25f);Scan(geometry);Check(Site(geometry).HitCount==0&&Site(geometry).Signal==0,"Actual individual probe coverage governs result");
 var normal=World();normal.SetProbeRange(.001f);Check(normal.ProbeRange==.25f,"Core minimum 0.25 AU");normal.SetProbeRange(128);Check(normal.ProbeRange==32,"Core maximum 32 AU");normal.SetProbeRange(3);Check(normal.ProbeRange==4,"Probe range snaps to legal steps");var combat=World(8,true);combat.SetProbeRange(.25f);Check(combat.ProbeRange==.5f,"Combat minimum 0.5 AU");combat.SetProbeRange(256);Check(combat.ProbeRange==64,"Combat maximum 64 AU");
 var snapshot=World();Check(snapshot.AnalyzeUtilityProbes(),"Snapshot starts");Check(!snapshot.AnalyzeUtilityProbes(),"Concurrent scan refused");snapshot.MoveProbeFormation(new(100,100,100));snapshot.UpdateUtility(snapshot.ProbeScanLeft+.01f);Check(Site(snapshot).Signal==100,"Changes during scan affect the next scan only");Scan(snapshot);Check(Site(snapshot).Signal==0,"Next scan uses repositioned probes");
 var presets=World();presets.SetProbeFormation("Pinpoint");presets.ScaleProbeSpacing(.7f);presets.SaveProbePreset("Hunt");var saved=DemoWorld.ProbePlannedAU(presets.ScanProbes[0]);presets.SetProbeFormation("Spread");Check(presets.ProbeFormation=="Spread"&&presets.ProbeRange==16,"Spread preset sets actual formation and range");Check(presets.LoadProbePreset("Hunt"),"Custom formation loads");Check(Vector3.Distance(saved,DemoWorld.ProbePlannedAU(presets.ScanProbes[0]))<.001f,"Custom formation restores relative offsets");var others=presets.ScanProbes.Skip(1).Select(DemoWorld.ProbePlannedAU).ToArray();presets.MoveSingleProbe(presets.ScanProbes[0].Id,saved+Vector3.UnitX);Check(presets.ScanProbes.Skip(1).Select(DemoWorld.ProbePlannedAU).SequenceEqual(others),"Single-probe move preserves other probes");
 var labels=World();var label=Site(labels);foreach(float strength in new[]{0f,24.9f,25f,74.9f,75f,99.9f,100f}){label.Signal=strength;Check((strength>=25)==(labels.ProbeResultGroup(label)=="Data Site"),"Group disclosure threshold "+strength);Check((strength>=75)==(labels.ProbeResultName(label)=="Test Archive"),"Name disclosure threshold "+strength);Check((strength==100)==labels.ProbeWarpable(label),"Warp disclosure threshold "+strength);}
 var skill=World();float strengthBefore=skill.EffectiveProbeStrength,durationBefore=skill.ScanDuration,deviationBefore=skill.ScanDeviationMultiplier;skill.Astrometrics=5;skill.AstrometricRangefinding=5;skill.AstrometricPinpointing=5;skill.AstrometricAcquisition=5;Check(skill.EffectiveProbeStrength>strengthBefore&&skill.ScanDuration<durationBefore&&skill.ScanDeviationMultiplier<deviationBefore,"All four astrometric skills affect strength/time/deviation");
 var target=World(8,true);target.SetProbeRange(.5f);target.ProbeCenter=Vector3.Zero;target.Targets=[new(){Id="ship",Name="Test escort",Kind=TargetKind.Raider,Hull=100,Profile=null,Position=new(1000,0,0),Signature=200},new(){Id="drone",DroneId="drone",Name="Test drone",Kind=TargetKind.Raider,Hull=100,Profile=null,Position=new(1200,0,0),Signature=200},new(){Id="wreck",Name="Wreck",Kind=TargetKind.Wreck,Position=new(1000,0,0)},new(){Id="can",Name="Cargo",Kind=TargetKind.Container,Position=new(1000,0,0)}];Scan(target);Check(target.UtilitySites.Any(s=>s.TargetId=="ship"&&s.Signal==100),"Combat probes resolve a real ship");Check(target.UtilitySites.Any(s=>s.TargetId=="drone"&&s.Kind=="Drone"&&s.Signal==100),"Combat probes resolve a real drone");Check(!target.UtilitySites.Any(s=>s.TargetId is "wreck" or "can"),"Wrecks and cargo excluded from combat probes");target.Targets[0].Hull=0;target.RefreshProbeResults();Check(target.UtilitySites.First(s=>s.TargetId=="ship").Signal==0,"Destroyed contact invalidates scan lock");
 var core=World();core.ProbeCenter=Vector3.Zero;core.Targets=[new(){Id="ship",Name="Test escort",Kind=TargetKind.Raider,Hull=100,Profile=new Ship(),Position=new(1000,0,0)}];Scan(core);Check(core.UtilitySites.First(s=>s.TargetId=="ship").Signal==0,"Core probes cannot resolve ships");
 var warp=World();warp.ProbeSelection="scan-unit";Check(!warp.WarpUtilitySite(),"Unresolved signature cannot warp");Scan(warp);Check(warp.BookmarkProbeResult("scan-unit")&&warp.Bookmarks.Last().Name=="Test Archive","Resolved signature creates a real bookmark");Check(warp.WarpUtilitySite()&&warp.Transit!=null,"Resolved signature starts actual AU-scale warp");
 var recover=World();float before=recover.ItemCount("ut_probe_core",false);Check(recover.RecoverActiveProbes(),"Recovery orders physical return");recover.UpdateUtility(2);Check(recover.ScanProbes.Count==8,"Recovery takes time");recover.UpdateUtility(1.1f);Check(recover.ScanProbes.Count==0&&recover.ItemCount("ut_probe_core",false)==before+8,"Recovery returns exactly eight actual cargo probes");
 var expiry=World();foreach(var p in expiry.ScanProbes)p.Life=1;float prior=expiry.ItemCount("ut_probe_core",false);expiry.UpdateUtility(2);Check(expiry.ScanProbes.Count==0&&expiry.ItemCount("ut_probe_core",false)==prior+8,"Expired connected probes auto-recover");
 var lost=World();foreach(var p in lost.ScanProbes)p.Connected=false;Check(!lost.AnalyzeUtilityProbes(),"Lost probes cannot analyze");Check(lost.ReconnectScanProbes()==8&&lost.ActiveScanProbes.Count()==8,"Reconnect restores actual lost probes");lost.ScanProbes[0].Enabled=false;Check(lost.ActiveScanProbes.Count()==7,"Disabled probe excluded from scan formation");Check(lost.DestroyScanProbe(lost.ScanProbes[0].Id)&&lost.ScanProbes.Count==7,"Destroy removes selected probe");lost.AnalyzeUtilityProbes();lost.CancelProbeAnalysis();Check(lost.ProbeJob==null&&lost.ProbeScanLeft==0,"Cancel clears pending analysis");lost.RecoverProbesForTransit();Check(lost.ScanProbes.Count==0,"Dock/jump recovery clears connected probes");
 var save=World();save.SetProbeRange(2);save.ScaleProbeSpacing(.8f);save.SaveProbePreset("Saved hunt");Site(save).Ignored=true;save.ProbeSelection="scan-unit";save.AnalyzeUtilityProbes();var json=System.Text.Json.JsonSerializer.Serialize(save.CaptureUtility());var restored=World(0);restored.RestoreUtility(System.Text.Json.JsonSerializer.Deserialize<UtilitySave>(json));Check(restored.ScanProbes.Count==8&&restored.ProbeLayoutCustomized&&restored.ProbePresets.Count==1,"Save preserves individual probes and custom formations");Check(restored.ProbeJob!=null&&restored.ProbeScanLeft>0&&restored.ProbeSelection=="scan-unit"&&Site(restored).Ignored,"Save preserves in-progress analysis, selection and ignored results");restored.UpdateUtility(restored.ProbeScanLeft+.01f);Check(restored.ProbeJob==null,"Restored scan completes");
 var equipment=World(0);equipment.Screen=ViewMode.Station;equipment.Grid="station";equipment.UtilityTrial("covert");var launcher=UtilityCatalog.All.First(d=>d.Kind=="CoreProbe");Check(equipment.FitUtility(launcher.Id,true,0),"Actual launcher fits a scan hull");equipment.CargoItems["ut_probe_core"]=8;Check(equipment.LoadUtilityPayload(0,"ut_probe_core",false),"Actual cargo probes load into launcher");equipment.EnterUtilityRange();equipment.UpdateUtility(20);Check(equipment.LaunchScanProbes(),"Scanner launch operates fitted module");equipment.UpdateUtility(launcher.Cycle+.1f);Check(equipment.ScanProbes.Count==8&&equipment.Player.Utilities[0].Loaded==0,"Launch consumes eight loaded inventory probes");
 Console.WriteLine($"{checks} probe scanning checks passed.");
 }
}
